


CREATE TABLE bal_spr_motors
    (bal_cn                         NUMBER(10,0) NOT NULL,
    typeid                         NUMBER,
    additionaltypeid               NUMBER,
    accgroup                       NUMBER(10,0),
    accclass                       NUMBER(10,0),
    saldo                          NUMBER DEFAULT 0
,
    part                           NUMBER(5,0),
    balname                        VARCHAR2(181),
    closebalance                   NUMBER DEFAULT 0

 ,
    ratedifference                 NUMBER DEFAULT 0


,
    currencyposition               NUMBER DEFAULT 0

 ,
    cashincoming                   NUMBER(*,0),
    clientcategory                 NUMBER(*,0),
    resident                       NUMBER(*,0),
    acctype                        NUMBER(*,0),
    sector                         NUMBER)
  PCTFREE     10
  PCTUSED     40
  INITRANS    1
  MAXTRANS    255
  TABLESPACE  smartbank
  STORAGE   (
    INITIAL     245760
    MINEXTENTS  1
    MAXEXTENTS  2147483645
  )
/




-- Comments for BAL_SPR_MOTORS

COMMENT ON COLUMN bal_spr_motors.acctype IS '0-cari 1-credit 2-deposit'
/
COMMENT ON COLUMN bal_spr_motors.cashincoming IS '0-NOT INCOMING ;1 INCOMING IN CASH REPORT'
/
COMMENT ON COLUMN bal_spr_motors.clientcategory IS '0 -fiziki 1 huquqi'
/
COMMENT ON COLUMN bal_spr_motors.closebalance IS '0- Uchastvuet,  1... NeUchastvuet'
/
COMMENT ON COLUMN bal_spr_motors.currencyposition IS '0- Uchastvuet,  1... NeUchastvuet'
/
COMMENT ON COLUMN bal_spr_motors.resident IS '0-ne rezident 1 rezident'
/
COMMENT ON COLUMN bal_spr_motors.sector IS 'Muesselerin tipleri'
/
COMMENT ON COLUMN bal_spr_motors.typeid IS '1-Active, 2-Passive, 3-Active-Passive'
/






